+    const ok = t && t.endsWith("?") && t.includes(o.start) && t.includes(LONG[o.day]) && o.partners.every((p) => t.includes(first(p.name))) && okNums(t, allowedIn(facts)) && !PRONOUN.test(t) && !/\bbook(ed)?\b/i.test(t) && t.split(/\s+/).length <= 40;
     if (ok) { const g = await guard.checkOut(t, { fallback: null }); if (!g.flagged) return { text: t, by: "model" }; }
   } catch { /* the template */ }
   return { text: template(o), by: "rules" };

